import{_ as e,o as s,c as o,a2 as n}from"./chunks/framework.DGu13UIe.js";const p=JSON.parse('{"title":"第 21 课 · 浏览器与 Node.js：为什么 HTML 能直开、.mjs 却要运行时？（扩展阅读）","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/21-js-runtimes/doc.md"},"headers":[],"relativePath":"chapters/21-js-runtimes.md","filePath":"chapters/21-js-runtimes.md"}'),r={name:"chapters/21-js-runtimes.md"};function a(d,t,i,l,g,h){return s(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="第-21-课-·-浏览器与-node-js-为什么-html-能直开、-mjs-却要运行时-扩展阅读" tabindex="-1">第 21 课 · 浏览器与 Node.js：为什么 HTML 能直开、<code>.mjs</code> 却要运行时？（扩展阅读） <a class="header-anchor" href="#第-21-课-·-浏览器与-node-js-为什么-html-能直开、-mjs-却要运行时-扩展阅读" aria-label="Permalink to &quot;第 21 课 · 浏览器与 Node.js：为什么 HTML 能直开、\`.mjs\` 却要运行时？（扩展阅读）&quot;">​</a></h1><p><strong>约 25 分钟</strong> · 纯阅读 · <a href="/bagent/chapters/19-web-stream.html">第 19–20 课</a> 之后</p><p>第 19 课 <strong><code>public/index.html</code> 双击就能跑</strong>；第 1 课起 <strong><code>node xxx.mjs</code> 要先装 Node</strong>。<br> 很多初学者会困惑：<strong>都是 JavaScript，凭什么一个「打开就行」、一个「还要装运行时」？</strong></p><p>本课把这件事讲清楚，并顺带介绍 <strong>Deno、Bun</strong> 等较新的 JS 运行时。</p><hr><h2 id="_1-先纠正一个直觉" tabindex="-1">1. 先纠正一个直觉 <a class="header-anchor" href="#_1-先纠正一个直觉" aria-label="Permalink to &quot;1. 先纠正一个直觉&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>更准确的说法</th></tr></thead><tbody><tr><td>「HTML 不需要运行时」</td><td><strong>需要</strong>——只是运行时已经装在你电脑里了，叫 <strong>浏览器</strong></td></tr><tr><td>「JS 文件双击就能跑」</td><td><strong>看宿主</strong>：嵌在 HTML 里、由浏览器加载 → 能跑；磁盘上的 <code>server.mjs</code> → <strong>没有默认宿主</strong>，双击只会用编辑器打开或报关联错误</td></tr><tr><td>「浏览器和 Node 是两种语言」</td><td><strong>同一种语言（ECMAScript）</strong>，<strong>不同的内置 API 与环境</strong></td></tr></tbody></table><p>你写的 <code>.mjs</code> / \`.js <strong>源码</strong>本身不能自己执行——总要有一个 <strong>宿主（host）</strong> 来解析、编译（JIT）、调用 API。</p><hr><h2 id="_2-打开一个-html-文件时发生了什么" tabindex="-1">2. 打开一个 HTML 文件时发生了什么 <a class="header-anchor" href="#_2-打开一个-html-文件时发生了什么" aria-label="Permalink to &quot;2. 打开一个 HTML 文件时发生了什么&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lessons/19-web-stream/public/index.html</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或 file:///Users/.../index.html</span></span></code></pre></div><p>流程可以粗分为：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  OS[操作系统]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Browser[浏览器进程]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Engine[JS 引擎 如 V8]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Page[HTML + CSS + script]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  OS --&gt;|启动| Browser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Browser --&gt;|解析渲染| Page</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Browser --&gt;|执行 script| Engine</span></span></code></pre></div><ol><li><strong>操作系统</strong> 按文件关联启动 <strong>Chrome / Safari / Firefox</strong> 等。</li><li><strong>浏览器</strong> 读 HTML，建 DOM，加载 CSS，遇到 <code>&lt;script&gt;</code> 交给 <strong>JS 引擎</strong>（Chrome 系多为 <strong>V8</strong>）。</li><li>脚本里能用 <strong><code>document</code>、<code>fetch</code>（有限制）、<code>localStorage</code></strong> 等——这些是 <strong>浏览器提供的 Web API</strong>，不是 JS 语法本身。</li></ol><p>所以：<strong>不是「HTML 免运行时」，而是「浏览器替你当了运行时 + UI 壳」</strong>。</p><h3 id="_2-1-为什么第-19-课不必起-node" tabindex="-1">2.1 为什么第 19 课不必起 Node <a class="header-anchor" href="#_2-1-为什么第-19-课不必起-node" aria-label="Permalink to &quot;2.1 为什么第 19 课不必起 Node&quot;">​</a></h3><p><a href="/bagent/chapters/19-web-stream.html"><code>public/index.html</code></a> 里：</p><ul><li><strong>假数据</strong> 用 <code>ReadableStream</code> 在页面内生成，<strong>不请求外网</strong></li><li><strong>不读</strong> <code>process.env</code>、<strong>不写</strong> 本地文件、<strong>不监听</strong> TCP 端口</li></ul><p>它用到的全是 <strong>浏览器里本来就有的能力</strong>，因此 <code>file://</code> 或双击即可。</p><p>一旦要 <strong>藏 API Key</strong>、<strong>代理 DeepSeek</strong>、<strong>监听 3020 端口</strong>，就超出了「纯页面」——需要 <a href="/bagent/chapters/20-web-stream-server.html">第 20 课</a> 的 <strong>Node 服务端</strong>。</p><hr><h2 id="_3-运行-node-lessons-01-deepseek-deepseek-mjs-时发生了什么" tabindex="-1">3. 运行 <code>node lessons/01-deepseek/deepseek.mjs</code> 时发生了什么 <a class="header-anchor" href="#_3-运行-node-lessons-01-deepseek-deepseek-mjs-时发生了什么" aria-label="Permalink to &quot;3. 运行 \`node lessons/01-deepseek/deepseek.mjs\` 时发生了什么&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lessons/01-deepseek/deepseek.mjs</span></span></code></pre></div><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Shell[终端]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Node[Node.js 进程]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  V8[V8 引擎]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Lib[libuv + 内置模块]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Shell --&gt;|启动| Node</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Node --&gt; V8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Node --&gt; Lib</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Lib --&gt;|fs fetch http| OS[操作系统]</span></span></code></pre></div><ol><li><strong>终端</strong> 启动 <strong><code>node</code> 可执行文件</strong>（Node.js 安装时带的）。</li><li>Node 把 <code>.mjs</code> 交给内嵌的 <strong>V8</strong> 执行（与 Chrome 同系引擎，但<strong>外壳不同</strong>）。</li><li>脚本里可用 <strong><code>process</code>、<code>fs</code>、<code>http</code></strong> 等——这是 <strong>Node 提供的 API</strong>，浏览器里 <strong>没有</strong> <code>require</code>/<code>import fs</code> 那一套（除非 bundler 打补丁）。</li></ol><p><strong>磁盘上的 <code>.mjs</code> 没有「默认关联程序」替你执行 JS</strong>——你必须显式调用 <code>node</code>（或 Deno、Bun 等）。</p><hr><h2 id="_4-浏览器-vs-node-对照表" tabindex="-1">4. 浏览器 vs Node：对照表 <a class="header-anchor" href="#_4-浏览器-vs-node-对照表" aria-label="Permalink to &quot;4. 浏览器 vs Node：对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>浏览器</th><th>Node.js</th></tr></thead><tbody><tr><td><strong>主要用途</strong></td><td>展示 UI、跑网页逻辑</td><td>脚本、CLI、HTTP 服务、工具链</td></tr><tr><td><strong>谁启动</strong></td><td>用户点链接 / 打开文件</td><td>你在终端敲 <code>node</code></td></tr><tr><td><strong>典型全局对象</strong></td><td><code>window</code>、<code>document</code></td><td><code>process</code>、<code>globalThis</code></td></tr><tr><td><strong>网络</strong></td><td><code>fetch</code>（受 <strong>同源策略 / CORS</strong> 约束）</td><td><code>fetch</code>、 <code>http</code>/<code>https</code> 模块，<strong>无 CORS</strong></td></tr><tr><td><strong>文件</strong></td><td>几乎不能直接读用户磁盘（安全）</td><td><code>fs</code> 读写任意路径（受 OS 权限约束）</td></tr><tr><td><strong>密钥</strong></td><td>写进 JS = <strong>谁都能看见</strong></td><td>放 <code>process.env</code>，不发给浏览器</td></tr><tr><td><strong>本课例子</strong></td><td>第 10、19 课页面</td><td>第 1–9、18、20 课 <code>.mjs</code></td></tr></tbody></table><p><strong>同一段语法</strong>（<code>async/await</code>、<code>fetch</code>、箭头函数）两边都能跑；<strong>换的是「能调哪些库、默认安全模型是什么」</strong>。</p><h3 id="_4-1-为什么-agent-课用-node-当-harness" tabindex="-1">4.1 为什么 Agent 课用 Node 当 Harness <a class="header-anchor" href="#_4-1-为什么-agent-课用-node-当-harness" aria-label="Permalink to &quot;4.1 为什么 Agent 课用 Node 当 Harness&quot;">​</a></h3><p><a href="/bagent/chapters/10-web-ui.html">第 10 课</a> 架构图里：<strong>浏览器只聊天，Agent 循环在 Node</strong>——因为：</p><ol><li><strong><code>DEEPSEEK_API_KEY</code> 不能进 <code>public/</code></strong></li><li><strong>Tool Calls、读文件、起子进程</strong> 更适合服务端</li><li>浏览器负责 <strong>展示</strong>；Node 负责 <strong>编排与密钥</strong></li></ol><p>第 20 课把 <strong>流式</strong> 也放回了 Node 网关，道理相同。</p><hr><h2 id="_5-「运行时」到底指什么" tabindex="-1">5. 「运行时」到底指什么 <a class="header-anchor" href="#_5-「运行时」到底指什么" aria-label="Permalink to &quot;5. 「运行时」到底指什么&quot;">​</a></h2><p>可以拆成三层理解：</p><table tabindex="0"><thead><tr><th>层</th><th>是什么</th><th>例子</th></tr></thead><tbody><tr><td><strong>语言</strong></td><td>ECMAScript 语法与语义</td><td><code>const</code>、<code>Promise</code>、<code>class</code></td></tr><tr><td><strong>引擎</strong></td><td>真正执行字节码</td><td><strong>V8</strong>、SpiderMonkey、JavaScriptCore</td></tr><tr><td><strong>运行时</strong></td><td>引擎 + 标准库 + 事件循环 + I/O</td><td><strong>浏览器</strong>、<strong>Node.js</strong>、<strong>Deno</strong>、<strong>Bun</strong></td></tr></tbody></table><p>你说「需要一个运行时」，通常指 <strong>第三层</strong>——缺了它，只有磁盘上的文本，没有 <code>console.log</code> 的归宿，也没有 <code>fetch</code> 的实现。</p><hr><h2 id="_6-较新的-javascript-运行时-2025–2026-概览" tabindex="-1">6. 较新的 JavaScript 运行时（2025–2026 概览） <a class="header-anchor" href="#_6-较新的-javascript-运行时-2025–2026-概览" aria-label="Permalink to &quot;6. 较新的 JavaScript 运行时（2025–2026 概览）&quot;">​</a></h2><p>Node（2009 年起）仍是 <strong>服务端 JS 事实标准</strong>，但近几年多了几个 <strong>「可替代 Node 的宿主」</strong>：</p><table tabindex="0"><thead><tr><th>运行时</th><th>一句话</th><th>和本课的关系</th></tr></thead><tbody><tr><td><strong>Node.js</strong></td><td>V8 + libuv；npm 生态最大</td><td><strong>bagent 默认</strong>；<code>npm run ch01</code> 等</td></tr><tr><td><strong>Deno</strong></td><td>默认 <strong>TypeScript</strong>、<strong>权限沙箱</strong>（读文件要 <code>--allow-read</code>）、标准库内置</td><td>可把本课 <code>.mjs</code> 改成 Deno 跑，思路相同</td></tr><tr><td><strong>Bun</strong></td><td>追求启动与安装速度；内置 bundler/test</td><td>常作 Node <strong>兼容替代</strong>跑脚本</td></tr><tr><td><strong>Cloudflare Workers</strong></td><td>边缘 V8 <strong>隔离</strong>，无传统 <code>fs</code>，有 <code>fetch</code>/KV</td><td>部署 <strong>无服务器</strong> 网关时代理 DeepSeek</td></tr><tr><td><strong>WinterCG</strong></td><td>推动 <strong><code>fetch</code>、<code>Request</code>、<code>Response</code></strong> 跨运行时一致</td><td>第 19 课 <code>fetch</code> + <code>ReadableStream</code> 在 Node 20+ 也能用，即此趋势</td></tr></tbody></table><p>不必现在全学。知道三点即可：</p><ol><li><strong>语法 largely 共用</strong>（ES 模块、<code>async/await</code>）</li><li><strong>API 与部署形态不同</strong>——Worker 没有完整 <code>fs</code>，Deno 默认更严</li><li><strong>选 Node 的原因</strong>通常是 <strong>教程生态、npm 包、团队熟悉度</strong>——不是唯一解</li></ol><hr><h2 id="_7-和第-19、20-课的对照-串起来" tabindex="-1">7. 和第 19、20 课的对照（串起来） <a class="header-anchor" href="#_7-和第-19、20-课的对照-串起来" aria-label="Permalink to &quot;7. 和第 19、20 课的对照（串起来）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你做的</th><th>用的宿主</th><th>为什么</th></tr></thead><tbody><tr><td>双击 <code>public/index.html</code>（第 18、19 课）</td><td><strong>浏览器</strong></td><td>页内填 Key，<code>fetch</code> 直连 DeepSeek</td></tr><tr><td><code>npm run ch20</code></td><td><strong>Node</strong></td><td>监听端口、真 DeepSeek</td></tr></tbody></table><p>若把第 20 课改成 <strong>Deno</strong> 或 <strong>Bun</strong>，HTTP 代理逻辑可以几乎不变；变的是启动命令（<code>deno run</code>、<code>bun run</code>）和权限/配置方式。</p><hr><h2 id="_8-常见追问" tabindex="-1">8. 常见追问 <a class="header-anchor" href="#_8-常见追问" aria-label="Permalink to &quot;8. 常见追问&quot;">​</a></h2><p><strong>Q：<code>import</code> 的 <code>.mjs</code> 为什么浏览器里也要 <code>&lt;script type=&quot;module&quot;&gt;</code>？</strong><br> A: 两边都实现了 <strong>ES Module</strong> 标准，但 <strong>模块解析规则不同</strong>——浏览器按 <strong>URL</strong> 找文件；Node 按 <strong>文件路径</strong> 找。浏览器不能直接 <code>import fs from &quot;node:fs&quot;</code>。</p><p><strong>Q：Vite / Webpack 算运行时吗？</strong><br> A: <strong>不算</strong>。它们是 <strong>构建工具</strong>，把源码打包成浏览器能加载的 bundle；真正执行仍在浏览器或 Node 里。</p><p><strong>Q：Python 课（第 12、14 课）和 JS 运行时什么关系？</strong><br> A: <strong>完全另一套运行时</strong>（CPython + transformers/FastAPI）。bagent 用 Python 演示 <strong>推理与假流式</strong>，JS 主线仍是 <strong>Agent 与网关</strong>。</p><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 能说出「HTML 能直开」是因为 <strong>浏览器已是运行时</strong> 吗？</li><li>[ ] 能区分 <strong>JS 引擎</strong> 与 <strong>运行时（Node / 浏览器）</strong> 吗？</li><li>[ ] 能解释为什么 API Key 应放在 <strong>Node 环境变量</strong> 而不是 HTML 吗？</li><li>[ ] 能举出除 Node 外 <strong>一个</strong> 新运行时（Deno / Bun / Workers）吗？</li></ul><h2 id="相关章节" tabindex="-1">相关章节 <a class="header-anchor" href="#相关章节" aria-label="Permalink to &quot;相关章节&quot;">​</a></h2><ul><li><a href="/bagent/chapters/19-web-stream.html">第 19 课 · 浏览器流式</a></li><li><a href="/bagent/chapters/20-web-stream-server.html">第 20 课 · Node 网关</a></li><li><a href="/bagent/chapters/10-web-ui.html">第 10 课 · 网页 Agent</a></li><li><a href="/bagent/chapters/17-sse-landscape.html">第 17 课 · SSE 行业背景</a></li></ul><p><a href="/bagent/chapters/20-web-stream-server.html">← 第 20 课</a> · <a href="/bagent/chapters/17-sse-landscape.html">第 17 课 SSE 背景 →</a> · <a href="https://nodejs.org/docs" target="_blank" rel="noreferrer">Node.js 文档</a> · <a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript" target="_blank" rel="noreferrer">MDN JavaScript</a> · <a href="https://docs.deno.com/" target="_blank" rel="noreferrer">Deno</a> · <a href="https://bun.sh/docs" target="_blank" rel="noreferrer">Bun</a></p>`,60)])])}const b=e(r,[["render",a]]);export{p as __pageData,b as default};
